SELECT SEQ as seq, EMP_NO as empNo, USER_NM as userNm, PROJ_CODE as projCode, PROJ_NAME as projName, CRTDATE as crtdate FROM contract_m
AND EMP_NO = #{empNo}
AND ( PROJ_NAME LIKE CONCAT('%', #{search}, '%') OR USER_NM LIKE CONCAT('%', #{search}, '%') )
ORDER BY SEQ DESC LIMIT #{pageable.offset}, #{pageable.pageSize}

SELECT COUNT(*) FROM contract_m
AND EMP_NO = #{empNo}
AND ( PROJ_NAME LIKE CONCAT('%', #{search}, '%') OR USER_NM LIKE CONCAT('%', #{search}, '%') )

SELECT * FROM ( SELECT m.seq, m.emp_no, m.user_nm, m.proj_code, m.proj_name, m.appr_no, d.cont_date, d.cont_period, d.move_date, d.cont_amt, d.deposit_amt, d.rent_amt, d.address, d.address_d, d.post_code, d.res_type, d.trans_type, d.area, d.crtdate, d.accu, d.accu_type, d.source, d.chk_1, d.chk_2, d.chk_3, d.chk_4, d.chk_5, d.chk_reason_1, d.chk_reason_2, d.chk_reason_3, d.chk_reason_4, d.chk_reason_5, a1.appr_stat, a1.appr_date, ROW_NUMBER() OVER (PARTITION BY m.appr_no ORDER BY m.seq) AS rn FROM contract_m m , contract_d d , approval_m a1 where m.seq = d.seq AND m.appr_no = a1.appr_no
AND m.proj_code = #{proj_code}
) sub WHERE rn = 1 ORDER BY sub.crtdate desc

